/* Wiki titles with border */
.arzaba-wiki.theme-dark .HyperMD-header-1,
.arzaba-wiki.theme-light .HyperMD-header-1 {
	padding-bottom: 0.4rem;
	border-bottom: 1px solid grey;
	margin-bottom: 0.6rem;
}

.theme-dark .workspace-tab-header-container {
	background-color: #0a0a0b;
}

.theme-light .workspace-tab-header-container {
	background-color: #efefe7;
}

.arzaba-ivy.theme-light .workspace-tab-header-container {
	background-color: #fff1f7;
}

.arzaba-ivy.theme-dark .workspace-tab-header-container {
	background-color: #3d2032;
}

.arzaba-wiki.theme-light .workspace-tab-header-container {
	background-color: #f1f3f5;
}

.arzaba-wiki.theme-dark .workspace-tab-header-container {
	background-color: #1b2026;
}

.arzaba-black-and-white.theme-light .workspace-tab-header-container {
	background-color: #f0f0f0;
}

.arzaba-black-and-white.theme-dark .workspace-tab-header-container {
	background-color: #111111;
}

.arzaba-future.theme-light .workspace-tab-header-container {
	background-color: #f2f2f9;
}

.arzaba-future.theme-dark .workspace-tab-header-container {
	background-color: #1a002b;
}

.arzaba-retro.theme-light .workspace-tab-header-container {
	background-color: #000000;
}

.arzaba-retro.theme-dark .workspace-tab-header-container {
	background-color: #000000;
}

.arzaba-past.theme-light .workspace-tab-header-container {
	background-color: #e6dccb;
}

.arzaba-past.theme-dark .workspace-tab-header-container {
	background-color: #2a211c;
}

/* Font size override */

.theme-light.arzaba-font-override,
.theme-dark.arzaba-font-override {
	--font-text-size: 22px !important;
}

.arzaba-ivy.theme-light.arzaba-font-override,
.arzaba-ivy.theme-dark.arzaba-font-override {
	--font-text-size: 20px !important;
}

.arzaba-wiki.theme-light.arzaba-font-override,
.arzaba-wiki.theme-dark.arzaba-font-override {
	--font-text-size: 18px !important;
}

.arzaba-black-and-white.theme-light.arzaba-font-override,
.arzaba-black-and-white.theme-dark.arzaba-font-override {
	--font-text-size: 26px !important;
}

.arzaba-future.theme-light.arzaba-font-override,
.arzaba-future.theme-dark.arzaba-font-override {
	--font-text-size: 20px !important;
}

.arzaba-retro.theme-light.arzaba-font-override,
.arzaba-retro.theme-dark.arzaba-font-override {
	--font-text-size: 34px !important
}

.arzaba-past.theme-light.arzaba-font-override,
.arzaba-past.theme-dark.arzaba-font-override {
	--font-text-size: 24px !important
}


/* Blur Prompt Background */

.modal-bg {
	background-color: #FFFFFF01;
	backdrop-filter: blur(3px);
}

div.popover.hover-popover,
.menu,
.suggestion-container {
	background-color: var(--background-primary);
	border: none;
}

/* Larger Math Font Size */

.math {
	font-size: 22px;
	line-height: 0.833333;
}

.math-block mjx-mtr:not(:first-child) mjx-mtd {
	padding-top: 1.0em !important;
}

/* Ivy Heart lists */

.arzaba-ivy.theme-dark:not(:is(.arzaba-past, .arzaba-retro, .arzaba-future, .arzaba-black-and-white, .arzaba-wiki)) .list-bullet.list-bullet.list-bullet:after,
.arzaba-ivy.theme-light:not(:is(.arzaba-past, .arzaba-retro, .arzaba-future, .arzaba-black-and-white, .arzaba-wiki)) .list-bullet.list-bullet.list-bullet:after {
	content: "♥";
	height: unset;
	width: unset;
	background: transparent;
	color: var(--text-accent);
}

/* Wiki titles with border */
.arzaba-wiki.theme-dark .HyperMD-header-1,
.arzaba-wiki.theme-light .HyperMD-header-1 {
	padding-bottom: 0.4rem;
	border-bottom: 1px solid grey;
	margin-bottom: 0.6rem;
}

